function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/** Wrap a string as trusted markup: it will be inserted verbatim by html. */
export function raw(text) {
  if (isHtmlResult(text)) return text;
  return { [MARKER]: true, toString: () => String(text) };
}

/** True for anything produced by html() or raw(). */
export function isHtmlResult(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    value[MARKER] === true &&
    typeof value.toString === 'function'
  );
}

/**
 * Tagged template literal for safe HTML.
 * Static parts are used as-is; interpolated values are escaped.
 * - html results and raw() wrappers pass through unescaped
 * - arrays (nested arbitrarily) are flattened and joined with no separator
 */
export function html(strings, ...values) {
  let out = '';
  for (let i = 0; i < strings.length; i++) {
    out += strings[i];
    if (i < values.length) out += renderValue(values[i]);
  }
  return { [MARKER]: true, toString: () => out };
}

function renderValue(value) {
  if (Array.isArray(value)) return value.map(renderValue).join('');
  if (isHtmlResult(value)) return value.toString();
  if (value === null || value === undefined) return '';
  return escapeHtml(value);
}
