import assert from 'node:assert/strict';

import { html, raw } from './index.mjs';

test('returns an object with toString, not a bare string', () => {
  const result = html`<p>hi</p>`;
  assert.equal(typeof result, 'object');
  assert.equal(result.toString(), '<p>hi</p>');
});

test('script-injection value renders inert', () => {
  const evil = '<script>alert(1)</script>';
  const result = html`<div>${evil}</div>`;
  assert.equal(
    result.toString(),
    '<div>&lt;script&gt;alert(1)&lt;/script&gt;</div>'
  );
  assert.ok(!result.toString().includes('<script>'));
});

test('escapes all five dangerous characters', () => {
  const result = html`${`&<>"'`}`;
  assert.equal(result.toString(), '&amp;&lt;&gt;&quot;&#39;');
});

test('attribute-position quote escaping prevents breaking out', () => {
  const input = '" onmouseover="alert(1)';
  const result = html`<a title="${input}">x</a>`;
  assert.equal(
    result.toString(),
    '<a title="&quot; onmouseover=&quot;alert(1)">x</a>'
  );
  // The injected attribute boundary never survives.
  assert.ok(!result.toString().includes('" onmouseover='));
});

test('array of nested html items joins without separators or double-escaping', () => {
  const items = ['a & b', '<c>', "d'e"];
  const list = html`<ul>${items.map((t) => html`<li>${t}</li>`)}</ul>`;
  assert.equal(
    list.toString(),
    '<ul><li>a &amp; b</li><li>&lt;c&gt;</li><li>d&#39;e</li></ul>'
  );
});

test('raw passthrough is not escaped', () => {
  const trusted = raw('<b>bold</b>');
  const result = html`<div>${trusted}</div>`;
  assert.equal(result.toString(), '<div><b>bold</b></div>');

  const mixed = html`<i>${[raw('<u>u</u>'), html`<s>${'<strike>'}</s>`]}</i>`;
  assert.equal(mixed.toString(), '<i><u>u</u><s>&lt;strike&gt;</s></i>');
});

test('double-escaping is absent two nesting levels deep', () => {
  const user = `<img src=x onerror="alert('&')">`;
  const inner = html`<td>${user}</td>`;
  const middle = html`<tr>${inner}</tr>`;
  const outer = html`<table>${middle}</table>`;
  assert.equal(
    outer.toString(),
    '<table><tr><td>&lt;img src=x onerror=&quot;alert(&amp;&#39;&amp;&#39;)&quot;&gt;</td></tr></table>'
  );
  assert.ok(!outer.toString().includes('&amp;lt;'));
  assert.ok(!outer.toString().includes('&amp;quot;'));
});
"})
